        assertTrue(actual.startsWith(pBaseStr + "["), actual);
        assertTrue(actual.endsWith("]"), actual);

        final String fieldsString = actual.substring(pBaseStr.length() + 1, actual.length() - 1);
        final HashMap<String, String> fields = new HashMap<>();
        for (final String field : fieldsString.split(",")) {
            final int eq = field.indexOf('=');
            assertTrue(eq > 0, "Expected field=value but was: " + field);
            fields.put(field.substring(0, eq), field.substring(eq + 1));
        }

        assertEquals(4, fields.size(), "Unexpected fields: " + fields);
        assertEquals("John Doe", fields.get("name"));
        assertEquals("33", fields.get("age"));
        assertEquals("false", fields.get("smoker"));
        assertEquals(pJobStr + "[title=Manager]", fields.get("job"));
    }

